/**
 * Genera el bloque HTML de enlaces internos para la página de un radar.
 * Enlaza al índice de radares, al archivo de su comunidad y a otros radares
 * de la misma carretera (lista «Otros radares en la <carretera>»).
 *
 * @param id id_unico del radar (tal como aparece en RELACIONADOS_RADARES)
 * @param datos mapa id -> { carretera, municipio } con los datos de cada radar
 *   (se pasa desde la página para no duplicar datos en este módulo)
 */
export function bloqueRadaresRelacionadosHtml(
  id: string,
  datos: Record<string, { carretera: string; municipio: string }> = {}
): string {
  const rel = RELACIONADOS_RADARES[id];
  if (!rel) return "";
  const propio = datos[id];
  const slugComunidad = slugifyES(rel.comunidad);
  const out: string[] = [];
  out.push('<nav class="radares-relacionados" aria-label="Radares relacionados">');
  out.push('<p class="rr-ver-todos"><a href="/radares/">Ver todos los radares</a>' +
    ` · <a href="/radares/comunidad/${slugComunidad}/">Radares en ${escHtml(rel.comunidad)}</a></p>`);
  if (rel.cercanos.length > 0) {
    const titulo = propio && propio.carretera
      ? `Otros radares en la ${escHtml(propio.carretera)}`
      : "Otros radares cercanos";
    out.push(`<h2 class="rr-titulo">${titulo}</h2><ul class="rr-lista">`);
    for (const cid of rel.cercanos) {
      const d = datos[cid];
      const etiqueta = d ? `${escHtml(d.carretera)} · ${escHtml(d.municipio)}` : escHtml(cid);
      out.push(`<li><a href="/radares/${escHtml(cid)}/">${etiqueta}</a></li>`);
    }
    out.push("</ul>");
  }
  out.push("</nav>");
  return out.join("\n");
}

function slugifyES(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function escHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
